import dataset from './generated/signature-details.json'
import type { SignatureCohortKey, SignatureEra } from '@/lib/types'

// Generated by backend/pipeline/signature/export.py for the full metrics page. Do not hand-edit the JSON.
// Server-only: the file is several hundred KB, so keep it out of client components.

export interface RegulationEraInfo extends SignatureEra {
  span: string
  rules: string
  seasonsCovered: number[]
  seasonsMissing: number[]
  driverEras: number
  scoredDriverEras: number
}

export interface SignatureAxisDetail {
  percentile: number | null
  p5: number | null
  p95: number | null
  score: number | null // field-spread units (robust z), weighted over sessions
  sessions: number
  samples: number // lap-corners for qualifying axes, stints for race axes
  rank: number | null // within the era, 1 = highest score
  rankOf: number | null
}

export interface SignatureTeammate {
  slug: string
  name: string
  sharedSessions: number
  sharedQuali: number
  sharedRaces: number
  qualiH2hPct: number | null // share of shared qualifying sessions where the driver's best lap was faster
  diffs: Record<string, number | null> // driver minus teammate, field-spread units
}

export interface SignatureWeekend {
  season: number
  round: number
  circuit: string | null
  meeting: string | null
  team: string | null
  qualiLaps: number | null
  raceLaps: number | null
  values: Record<string, number | null> // field-spread units for that session
}

export interface SignatureEraDetail {
  era: SignatureEra
  seasons: number[]
  teams: Record<string, number>
  qualiSessions: number
  raceSessions: number
  sampleSize: number
  confidence: number | null
  axes: Record<string, SignatureAxisDetail>
  raw: {
    quali: {
      brakePointDeltaM: number | null
      minSpeedDeltaKmh: number | null
      releaseSpeedDeltaKmh: number | null
      fullThrottleDeltaM: number | null
    } | null
    race: {
      spreadDeltaS: number | null
      degDeltaSPerLap: number | null
      spreadS: number | null
      degSPerLap: number | null
    } | null
  }
  cohorts: Record<SignatureCohortKey, (number | null)[]>
  teammates: SignatureTeammate[]
  weekends: SignatureWeekend[]
}

export interface SignatureMethodology {
  quali: {
    lapsPerDriver: number
    personalCutoffPct: number
    sessionCutoffPct: number
    minFieldLapsPerCorner: number
    cornerProminenceKmh: number
    fullThrottlePct: number
    throttleLiftPct: number
  }
  race: {
    minGapAheadS: number
    stintPaceCutoffPct: number
    fuelEffectSPerLap: number
    minLapsConsistency: number
    minLapsDegradation: number
    minCompoundStints: number
  }
  scoring: {
    zClip: number
    minQualiSessions: number
    minQualiSamples: number
    minRaceSessions: number
    minRaceStints: number
    bootstrapN: number
  }
}

export interface SignatureCoverageSeason {
  season: number
  weekends: number
  pending: number
  qualiOk: number
  raceOk: number
  skipped: { round: number; meeting: string; part: string; detail: string }[]
}

export interface SignaturePeer {
  slug: string
  name: string
  team: string | null
  values: (number | null)[]
}

export interface SignatureReference {
  generatedAt: string
  pipelineVersion: string
  source: string
  seasons: number[]
  sessions: { quali: number; race: number }
  axes: string[]
  axisGroups: { quali: string[]; race: string[] }
  eras: RegulationEraInfo[]
  methodology: SignatureMethodology
  coverage: SignatureCoverageSeason[]
  champions: { season: number; slug: string; name: string }[]
  peers: Record<string, SignaturePeer[]>
}

export interface DriverSignatureMetrics {
  name: string
  defaultEra: string
  eras: Record<string, SignatureEraDetail>
}

interface SignatureDetailsDataset extends SignatureReference {
  drivers: Record<string, DriverSignatureMetrics>
}

const DATA = dataset as unknown as SignatureDetailsDataset

export function getSignatureMetrics(slug: string): DriverSignatureMetrics | null {
  return DATA.drivers[slug] ?? null
}

export function getSignatureReference(): SignatureReference {
  return DATA
}
